 if(!$('#fg-map-layer-style')){const st=document.createElement('style');st.id='fg-map-layer-style';st.textContent='.fg-map-layer{border:1px solid #d8e3ec;background:#fff;color:#23415f;border-radius:8px;padding:8px 10px;font-size:12px;font-weight:700}.fg-map-layer.active{background:#17365d;color:#fff;border-color:#17365d}';document.head.append(st)}
