function setFleetMapLayer(name){if(!fgFleetMap||!fgFleetBaseLayers[name])return;Object.values(fgFleetBaseLayers).forEach(l=>fgFleetMap.removeLayer(l));fgFleetBaseLayers[name].addTo(fgFleetMap);fgFleetSelectedLayer=name}
