async function checkedUpdate(table, values, column, value, label){
  const {data,error}=await sb.from(table).update(values).eq(column,value).select('*').maybeSingle();
  if(error) throw new Error(`${label}: ${error.message}`);
  if(!data) throw new Error(`${label}: no row was updated. Check your manager login and Supabase UPDATE/SELECT policies.`);
  return data;
}
function closeAppModal(){ $('#fg-modal-shade')?.remove(); }
function appModal({title,subtitle,fields,submitLabel='Save assignment',onSubmit}){
  closeAppModal();
  const shade=document.createElement('div');shade.id='fg-modal-shade';shade.innerHTML=`<section id="fg-modal" role="dialog" aria-modal="true" aria-labelledby="fg-modal-title"><h2 id="fg-modal-title">${safe(title)}</h2><p>${safe(subtitle||'Choose the details and save them to your fleet workspace.')}</p><form id="fg-modal-form">${fields}<div id="fg-modal-error" role="alert"></div><div class="fg-modal-actions"><button type="button" id="fg-modal-cancel">Cancel</button><button class="primary" type="submit" id="fg-modal-submit">${safe(submitLabel)}</button></div></form></section>`;
  document.body.append(shade);shade.addEventListener('click',e=>{if(e.target===shade)closeAppModal()});$('#fg-modal-cancel').onclick=closeAppModal;
  $('#fg-modal-form').addEventListener('submit',async e=>{e.preventDefault();const b=$('#fg-modal-submit'),err=$('#fg-modal-error');b.disabled=true;b.textContent='Saving…';err.textContent='';try{await onSubmit(new FormData(e.currentTarget));closeAppModal()}catch(ex){err.textContent=ex.message||'Could not save. Please try again.';b.disabled=false;b.textContent=submitLabel}});
  $('#fg-modal-form input, #fg-modal-form select, #fg-modal-form textarea')?.focus();
}
function optionList(items,selected='',placeholder='Select an option') { return `<option value="">${safe(placeholder)}</option>`+items.map(x=>`<option value="${safe(x.value)}" ${x.value===selected?'selected':''}>${safe(x.label)}</option>`).join(''); }
async function assignDriver(t){
  try{await loadManager();t=m.trucks.find(x=>x.id===t.id)||t;if(!m.drivers.length)throw Error('No registered driver accounts found. Ask the driver to register first.');
    appModal({title:'Assign driver to vehicle',subtitle:`Vehicle: ${t.reg_no||t.id}. Select the driver who will use this vehicle.`,fields:`<label for="fg-driver-select">Driver</label><select id="fg-driver-select" name="driver" required>${optionList(m.drivers.map(d=>({value:d.id,label:`${d.full_name||'Driver'} · ${d.mobile||d.id}${d.truck_id&&d.truck_id!==t.id?' · currently assigned':''}`})),t.driver_id||'','Choose a registered driver')}</select><label for="fg-unassign">Assignment action</label><select id="fg-unassign" name="action"><option value="assign">Assign selected driver</option><option value="unassign">Unassign this vehicle</option></select>`,submitLabel:'Save assignment',onSubmit:async fd=>{
      const action=fd.get('action'),driverId=fd.get('driver');
      if(action==='unassign'){if(t.driver_id)await checkedUpdate('profiles',{truck_id:null},'id',t.driver_id,'Clear previous driver profile');await checkedUpdate('trucks',{driver_id:null},'id',t.id,'Unassign vehicle');}
      else {if(!driverId)throw Error('Please select a driver.');const d=m.drivers.find(x=>x.id===driverId);if(!d)throw Error('That driver is no longer available. Refresh and try again.');if(d.truck_id&&d.truck_id!==t.id){for(const other of m.trucks.filter(x=>x.id===d.truck_id||x.driver_id===d.id))if(other.id!==t.id&&other.driver_id===d.id)await checkedUpdate('trucks',{driver_id:null},'id',other.id,'Clear driver from previous vehicle');}
        if(t.driver_id&&t.driver_id!==driverId)await checkedUpdate('profiles',{truck_id:null},'id',t.driver_id,'Clear previous driver profile');
        for(const other of m.trucks.filter(x=>x.id!==t.id&&x.driver_id===driverId))await checkedUpdate('trucks',{driver_id:null},'id',other.id,'Clear driver from previous vehicle');
        await checkedUpdate('trucks',{driver_id:driverId},'id',t.id,'Assign driver');await checkedUpdate('profiles',{truck_id:t.id},'id',driverId,'Update driver profile');
      }
      await loadManager();const verified=action==='unassign'?!m.trucks.find(x=>x.id===t.id)?.driver_id:(m.trucks.find(x=>x.id===t.id)?.driver_id===driverId&&m.drivers.find(x=>x.id===driverId)?.truck_id===t.id);if(!verified)throw Error('Supabase did not confirm the assignment. Check manager permissions and database policies.');toast2(action==='unassign'?'Vehicle unassigned.':'Driver and vehicle assignment saved.');
    }});
  }catch(e){toast2('Assignment failed: '+(e.message||String(e)));}
}
async function assignVehicle(d){
  try{await loadManager();d=m.drivers.find(x=>x.id===d.id)||d;if(!m.trucks.length)throw Error('Add a vehicle first.');
    appModal({title:'Assign vehicle to driver',subtitle:`Driver: ${d.full_name||d.id}. Select the vehicle for this driver.`,fields:`<label for="fg-vehicle-select">Vehicle</label><select id="fg-vehicle-select" name="vehicle" required>${optionList(m.trucks.map(t=>({value:t.id,label:`${t.reg_no||t.id}${t.driver_id&&t.driver_id!==d.id?' · assigned to another driver':''}`})),d.truck_id||'','Choose a vehicle')}</select><label for="fg-vehicle-action">Assignment action</label><select id="fg-vehicle-action" name="action"><option value="assign">Assign selected vehicle</option><option value="unassign">Unassign this driver</option></select>`,submitLabel:'Save assignment',onSubmit:async fd=>{const action=fd.get('action'),vehicleId=fd.get('vehicle');if(action==='unassign'){for(const t of m.trucks.filter(x=>x.driver_id===d.id))await checkedUpdate('trucks',{driver_id:null},'id',t.id,'Unassign vehicle');await checkedUpdate('profiles',{truck_id:null},'id',d.id,'Clear driver profile');}else{if(!vehicleId)throw Error('Please select a vehicle.');const t=m.trucks.find(x=>x.id===vehicleId);if(!t)throw Error('Vehicle not found. Refresh and try again.');if(t.driver_id&&t.driver_id!==d.id)await checkedUpdate('profiles',{truck_id:null},'id',t.driver_id,'Clear previous driver profile');for(const other of m.trucks.filter(x=>x.id!==t.id&&x.driver_id===d.id))await checkedUpdate('trucks',{driver_id:null},'id',other.id,'Clear previous vehicle');await checkedUpdate('trucks',{driver_id:d.id},'id',t.id,'Assign vehicle');await checkedUpdate('profiles',{truck_id:t.id},'id',d.id,'Update driver profile');}await loadManager();const v=m.drivers.find(x=>x.id===d.id);if(action==='assign'&&(!v||v.truck_id!==vehicleId))throw Error('Supabase did not confirm the driver profile update.');toast2(action==='unassign'?'Driver unassigned.':'Vehicle assigned to driver.');}});
  }catch(e){toast2('Assignment failed: '+(e.message||String(e)));}
}
async function assignAnyVehicle(){await loadManager();if(!m.drivers.length||!m.trucks.length)return toast2('Add a vehicle and have the driver register first.');appModal({title:'Assign vehicle',subtitle:'Choose a registered driver and a vehicle.',fields:`<label for="fg-driver-select">Driver</label><select id="fg-driver-select" name="driver" required>${optionList(m.drivers.map(d=>({value:d.id,label:d.full_name||d.id})))}</select><label for="fg-vehicle-select">Vehicle</label><select id="fg-vehicle-select" name="vehicle" required>${optionList(m.trucks.map(t=>({value:t.id,label:t.reg_no||t.id})))}</select>`,submitLabel:'Assign vehicle',onSubmit:async fd=>{const d=m.drivers.find(x=>x.id===fd.get('driver')),t=m.trucks.find(x=>x.id===fd.get('vehicle'));if(!d||!t)throw Error('Select both a driver and vehicle.');if(t.driver_id&&t.driver_id!==d.id)await checkedUpdate('profiles',{truck_id:null},'id',t.driver_id,'Clear previous driver profile');for(const other of m.trucks.filter(x=>x.id!==t.id&&x.driver_id===d.id))await checkedUpdate('trucks',{driver_id:null},'id',other.id,'Clear previous vehicle');await checkedUpdate('trucks',{driver_id:d.id},'id',t.id,'Assign vehicle');await checkedUpdate('profiles',{truck_id:t.id},'id',d.id,'Update driver profile');await loadManager();if(m.trucks.find(x=>x.id===t.id)?.driver_id!==d.id||m.drivers.find(x=>x.id===d.id)?.truck_id!==t.id)throw Error('Assignment was not confirmed by the database.');toast2(`${d.full_name||'Driver'} assigned to ${t.reg_no||t.id}.`);}});}
async function addVehicle(){const reg=prompt('Vehicle registration number (e.g. JH 01 AB 4821):');if(!reg||reg.trim().length<4)return;const id='TRK-'+crypto.randomUUID().slice(0,8).toUpperCase();const {error}=await sb.from('trucks').insert({id,reg_no:reg.trim().toUpperCase(),status:'stopped',fuel_pct:100,speed:0});if(error)return toast2(error.message);toast2('Vehicle added. Assign a registered driver from the Vehicles page.');await loadManager()}
async function createTrip(){
 await loadManager();const available=m.trucks.filter(t=>t.driver_id&&m.drivers.some(d=>d.id===t.driver_id));if(!available.length)return toast2('Assign a registered driver to a vehicle first.');
 appModal({title:'Assign a ride / trip',subtitle:'This trip will appear in the selected driver’s My Trip page and profile after saving.',fields:`<label for="fg-trip-vehicle">Vehicle and driver</label><select id="fg-trip-vehicle" name="truck" required>${optionList(available.map(t=>{const d=m.drivers.find(x=>x.id===t.driver_id);return {value:t.id,label:`${t.reg_no||t.id} — ${d.full_name||'Driver'}`}}))}</select><label for="fg-trip-origin">Pickup / starting point</label><input id="fg-trip-origin" name="origin" required minlength="2" maxlength="160" placeholder="e.g. Ranchi warehouse"/><label for="fg-trip-destination">Destination</label><input id="fg-trip-destination" name="destination" required minlength="2" maxlength="160" placeholder="e.g. Kolkata depot"/><label for="fg-trip-scheduled">Scheduled departure (optional)</label><input id="fg-trip-scheduled" name="scheduled" type="datetime-local"/><label for="fg-trip-notes">Instructions for driver (optional)</label><textarea id="fg-trip-notes" name="notes" maxlength="1000" placeholder="Delivery details, contact or special instructions"></textarea>`,submitLabel:'Assign trip to driver',onSubmit:async fd=>{const t=available.find(x=>x.id===fd.get('truck')),d=t&&m.drivers.find(x=>x.id===t.driver_id),origin=String(fd.get('origin')||'').trim(),destination=String(fd.get('destination')||'').trim();if(!t||!d)throw Error('Select a valid vehicle with an assigned driver.');if(origin.length<2||destination.length<2)throw Error('Enter both a starting point and destination.');const payload={truck_id:t.id,driver_id:d.id,manager_id:session.user.id,origin,destination,status:'assigned',notes:String(fd.get('notes')||'').trim()||null};const scheduled=fd.get('scheduled');if(scheduled)payload.scheduled_at=new Date(scheduled).toISOString();const {data,error}=await sb.from('trip_assignments').insert(payload).select('*').single();if(error)throw error;await loadManager();if(!m.trips.some(x=>x.id===data.id))throw Error('Trip was saved but could not be verified in the manager list. Refresh the page.');toast2(`Trip assigned to ${d.full_name||'driver'}. It will appear in their driver profile.`);}});
}
async function updateTripManager(t){const status=prompt('Enter status: assigned, started, completed, cancelled',t.status);if(!status)return;if(!['assigned','started','completed','cancelled'].includes(status))return toast2('Invalid trip status.');const {error}=await sb.from('trip_assignments').update({status}).eq('id',t.id);if(error)return toast2(error.message);toast2('Trip updated.');await loadManager()}
function proofActions(f){const wrap=document.createElement('div');wrap.style.display='flex';wrap.style.gap='6px';wrap.style.flexWrap='wrap';wrap.append(actionBtn('View bill',()=>openProof(f.bill_path,'Bill photo')),actionBtn('View video',()=>openProof(f.video_path,'Pump video')),actionBtn('Review',()=>reviewFuelLive(f)));return wrap}
async function openProof(path,label){if(!path)return toast2('No file path recorded for this proof.');const win=window.open('about:blank','_blank');try{const {data,error}=await sb.storage.from('fuel-proofs').createSignedUrl(path,300);if(error)throw error;if(win)win.location.href=data.signedUrl;else toast2('Your browser blocked the new tab. Allow pop-ups and try again.');}catch(e){if(win)win.close();toast2(label+' unavailable: '+e.message)}}
async function reviewFuelLive(f){const action=prompt(`Review fuel log ${f.id}\nType VERIFIED or FLAGGED`);if(!action)return;const a=action.trim().toLowerCase();const status=a==='verified'?'verified':a==='flagged'?'flagged':null;if(!status)return toast2('Enter VERIFIED or FLAGGED.');const {error}=await sb.from('fuel_logs').update({status}).eq('id',f.id);if(error)return toast2(error.message);toast2('Fuel log marked '+status+'.');await loadManager()}
async function resolveAlert(a){if(a.resolved)return;const {error}=await sb.from('alerts').update({resolved:true}).eq('id',a.id);if(error)return toast2(error.message);toast2('Alert marked resolved.');await loadManager()}
function exportRows(name,rows){if(!rows?.length)return toast2('No records to export.');const keys=[...new Set(rows.flatMap(Object.keys))];const csv=[keys,...rows.map(r=>keys.map(k=>r[k]??''))].map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download='fuelguard-'+name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
let knownDriverTripIds=null;let lastFuelSubmission=null;
function renderDriverNotifications(trips){
 const page=$('#page-alerts'); if(!page)return;
 let panel=page.querySelector('.panel'); if(!panel){panel=document.createElement('div');panel.className='panel';page.append(panel)}
 panel.replaceChildren();
 if(!trips.length){const empty=document.createElement('div');empty.className='empty';empty.textContent='No trip notifications yet. New assignments from your manager will appear here.';panel.append(empty);return}
 for(const t of trips.slice(0,12)){
  const row=document.createElement('div');row.className='activity';
  const ico=document.createElement('div');ico.className='activity-icon';ico.textContent='⇄';
  const copy=document.createElement('div');copy.className='activity-copy';
  const title=document.createElement('b');title.textContent=t.status==='assigned'?'New trip assigned':t.status==='started'?'Trip in progress':t.status==='completed'?'Trip completed':'Trip update';
  const detail=document.createElement('small');detail.textContent=`${t.origin||'—'} → ${t.destination||'—'} · ${t.created_at?new Date(t.created_at).toLocaleString():'Just now'}`;
  copy.append(title,detail);const badge=document.createElement('span');badge.className='status '+(['started','completed'].includes(t.status)?'verified':'');badge.textContent=labelStatus(t.status);row.append(ico,copy,badge);panel.append(row);
 }
}
async function loadDriver({notify=true}={}){
 const {data:trips,error}=await sb.from('trip_assignments').select('*').eq('driver_id',session.user.id).order('created_at',{ascending:false}).limit(50);
 if(error)throw error;
 const oldIds=knownDriverTripIds;
 currentTrips=trips||[];
 const assignedVehicle=currentTrips.find(t=>['assigned','started'].includes(t.status))?.truck_id;
 if(!myTruck&&assignedVehicle){const vr=await sb.from('trucks').select('*').eq('id',assignedVehicle).eq('driver_id',session.user.id).maybeSingle();if(!vr.error&&vr.data)myTruck=vr.data;}
 knownDriverTripIds=new Set(currentTrips.map(t=>t.id));
 const newlyAssigned=oldIds?currentTrips.find(t=>!oldIds.has(t.id)&&t.status==='assigned'):null;
 const latest=currentTrips.find(t=>['assigned','started'].includes(t.status))||null;
 if(notify&&newlyAssigned){toast2(`New trip assigned: ${newlyAssigned.origin} → ${newlyAssigned.destination}`);}
 const tripPage=$('#page-trip');
 if(tripPage){
  let card=$('#fg-driver-assignment');
  if(!card){card=document.createElement('section');card.id='fg-driver-assignment';card.setAttribute('aria-live','polite');const title=tripPage.querySelector('.page-title');if(title)title.after(card);else tripPage.prepend(card)}
  if(latest){const truck=myTruck;card.innerHTML=`<h3>✓ ${latest.status==='started'?'Your trip is active':'You are assigned to this ride'}</h3><div class="fg-trip-meta"><div><small>Route</small><strong>${safe(latest.origin)} → ${safe(latest.destination)}</strong></div><div><small>Vehicle</small><strong>${safe(truck?.reg_no||truck?.id||latest.truck_id||'Loading vehicle')}</strong></div><div><small>Trip status</small><strong>${safe(labelStatus(latest.status))}</strong></div><div><small>Assigned on</small><strong>${latest.created_at?new Date(latest.created_at).toLocaleString():'Just assigned'}</strong></div></div>${latest.scheduled_at?`<p style="margin:12px 0 0;color:#426a53"><b>Departure:</b> ${safe(new Date(latest.scheduled_at).toLocaleString())}</p>`:''}${latest.notes?`<p style="margin:8px 0 0;color:#426a53"><b>Manager instructions:</b> ${safe(latest.notes)}</p>`:''}`}
  else{card.innerHTML='<h3>No active trip</h3><div>Your active trip will appear here when your manager assigns one.</div>'}
 }
 // Keep the dashboard's Active Trip card connected to the same database record.
 const hero=$('#page-home .hero');
 if(hero){
  const label=hero.querySelector('.hero-label');const heading=hero.querySelector('h2');const desc=hero.querySelector('.hero-inner > p');const meta=hero.querySelectorAll('.hero-meta > div');
  if(latest){if(label)label.textContent=latest.status==='started'?'ACTIVE TRIP · IN PROGRESS':'ACTIVE TRIP · ASSIGNED';if(heading)heading.textContent=`${latest.origin||'Starting point'} → ${latest.destination||'Destination'}`;if(desc)desc.textContent=latest.status==='started'?'Your trip is in progress. Your assignment remains active until the trip is completed.':'Your manager assigned this ride. Open My Trip for the route and instructions.';if(meta[0]?.querySelector('b'))meta[0].querySelector('b').textContent=myTruck?.reg_no||myTruck?.id||latest.truck_id||'—';if(meta[1]?.querySelector('b'))meta[1].querySelector('b').textContent=latest.id;if(meta[2]?.querySelector('b'))meta[2].querySelector('b').textContent=labelStatus(latest.status)}
  else{if(label)label.textContent='NO ACTIVE TRIP';if(heading)heading.textContent='No active trip assigned';if(desc)desc.textContent='When your manager assigns a ride, it will appear here automatically.';if(meta[0]?.querySelector('b'))meta[0].querySelector('b').textContent=myTruck?.reg_no||myTruck?.id||'No vehicle';if(meta[1]?.querySelector('b'))meta[1].querySelector('b').textContent='—';if(meta[2]?.querySelector('b'))meta[2].querySelector('b').textContent='No active trip'}
 }
 const route=$('#page-trip .trip-route');
 if(route){const nodes=route.querySelectorAll('b');if(nodes[0])nodes[0].textContent=latest?.origin||'No trip assigned';if(nodes[1])nodes[1].textContent=latest?.destination||'Waiting for manager'}
 await renderJourneyControls(latest);
 ['trip-status','trip-tag','hero-status'].forEach(id=>{if($('#'+id))$('#'+id).textContent=latest?labelStatus(latest.status):'No active trip'});
 const starts=$$('button[onclick*="updateTrip"]');starts.forEach(b=>{const isStart=(b.textContent||'').toLowerCase().includes('start trip');const isComplete=(b.textContent||'').toLowerCase().includes('completed');b.disabled=!latest||latest.status==='completed'||latest.status==='cancelled'||(isStart&&latest.status==='started')||(isComplete&&latest.status!=='started')});
 const n=$('.profile h2');if(n)n.textContent=me.full_name||session.user.email;
 const details=$$('.profile-details b');if(details[0])details[0].textContent=me.full_name||'Driver';if(details[1])details[1].textContent=myTruck?.reg_no||myTruck?.id||'No vehicle assigned';if(details[2])details[2].textContent='Driver';if(details[3])details[3].textContent='Connected securely';
 const note=$('.profile .note');if(note){note.innerHTML=latest?`<span>✓</span><div><b>${latest.status==='started'?'Active trip':'Assigned to a ride'}</b><br>${safe(latest.origin)} → ${safe(latest.destination)}<br>Vehicle: ${safe(myTruck?.reg_no||myTruck?.id||latest.truck_id)} · Status: ${safe(labelStatus(latest.status))}<br><small>Your assigned ride and updates sync with your fleet manager.</small></div>`:'<span>✓</span><div><b>Connected securely</b><br>No active trip assigned yet. Your manager’s next trip assignment will appear here automatically.</div>'}
 renderDriverNotifications(currentTrips);
 await loadDriverFuel();
}
async function renderJourneyControls(trip){
 const page=$('#page-trip');if(!page)return;
 let panel=$('#fg-journey-controls');if(!panel){panel=document.createElement('section');panel.id='fg-journey-controls';panel.style.cssText='margin:16px 0;padding:18px;background:#fff;border:1px solid #dce8e0;border-radius:14px;box-shadow:0 8px 24px #15385b08';const grid=page.querySelector('.grid2');if(grid)grid.before(panel);else page.append(panel)}
 if(!trip){panel.innerHTML='<h3 style="margin:0 0 6px">Journey checkpoints</h3><p style="color:#8293a6;margin:0">No active assigned trip. When a manager assigns a trip, start/break/resume/end controls will appear here.</p>';return}
 currentJourneyEvent=null;journeyTableReady=true;
 if(trip.status==='started'){
  const {data,error}=await sb.from('trip_journey_events').select('id,event_type,created_at,odometer_km,fuel_level,fuel_pct,lat,lng,dashboard_photo_path').eq('trip_id',trip.id).order('created_at',{ascending:false}).limit(1).maybeSingle();
  if(error){journeyTableReady=false;panel.innerHTML=`<h3 style="margin:0 0 6px">Journey checkpoints</h3><p style="color:#a34b43">Journey-event database setup is missing or unavailable. Ask the manager to run <b>supabase-trip-journey-events.sql</b> in Supabase SQL Editor. Details: ${safe(error.message)}</p>`;return}
  currentJourneyEvent=data||null;
 }
 const onBreak=currentJourneyEvent?.event_type==='break_start';
 const title=trip.status==='assigned'?'Ready to start?':onBreak?'Driver is on break':'Trip in progress';
 const desc=trip.status==='assigned'?'Take a dashboard photo to record starting odometer and fuel.':onBreak?'Take a new dashboard photo before resuming the trip.':'Every break and trip end requires a new dashboard photo.';
 let buttons='';
 if(trip.status==='assigned')buttons='<button type="button" class="btn green" id="fg-start-trip">📷 Start Trip · dashboard photo required</button>';
 else if(onBreak)buttons='<button type="button" class="btn green" id="fg-resume-trip">📷 Resume Trip · dashboard photo required</button>';
 else buttons='<button type="button" class="btn outline" id="fg-take-break">☕ Take Break · dashboard photo required</button><button type="button" class="btn danger" id="fg-end-ride">🏁 End Ride · final dashboard photo required</button>';
 panel.innerHTML=`<div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start;flex-wrap:wrap"><div><h3 style="margin:0 0 6px;color:#203b54">${title}</h3><p style="margin:0 0 14px;color:#718398;font-size:12px">${desc}</p></div><span style="font-size:11px;font-weight:800;color:${onBreak?'#986a16':'#288455'};background:${onBreak?'#fff4d8':'#e9f7ef'};padding:7px 9px;border-radius:7px">${onBreak?'ON BREAK':trip.status==='assigned'?'NOT STARTED':'IN PROGRESS'}</span></div><div style="display:flex;gap:9px;flex-wrap:wrap">${buttons}</div><div style="margin-top:12px;font-size:11px;color:#8796a5">Each checkpoint saves a private dashboard photo, odometer, fuel gauge, GPS coordinates and timestamp.</div>`;
 $('#fg-start-trip')?.addEventListener('click',beginTripStartVerification);
 $('#fg-take-break')?.addEventListener('click',()=>beginJourneyEvent('break_start'));
 $('#fg-resume-trip')?.addEventListener('click',()=>beginJourneyEvent('resume'));
 $('#fg-end-ride')?.addEventListener('click',()=>beginJourneyEvent('end'));
}
async function analyzeDashboardPhoto(photo,trip,eventType){
 if(!['image/jpeg','image/png','image/webp'].includes(photo.type))throw new Error('Use a JPG, PNG or WebP dashboard photo for AI analysis.');
 if(photo.size>10*1024*1024)throw new Error('Dashboard photo must be 10 MB or smaller.');
 const ext=(photo.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,'').slice(0,8)||'jpg';
 const checkpointMap={start:'start_trip',break_start:'take_break',resume:'resume_trip',end:'end_ride'};
 const checkpoint=checkpointMap[eventType]||'start_trip';
 const imagePath=`${session.user.id}/${myTruck.id}/${trip.id}/${checkpoint}-${crypto.randomUUID()}.${ext}`;
 const {error:uploadError}=await sb.storage.from('dashboard-photos').upload(imagePath,photo,{upsert:false,contentType:photo.type});
 if(uploadError)throw new Error('Private dashboard photo upload failed: '+uploadError.message);
 const {data,error}=await sb.functions.invoke('analyze-dashboard',{body:{image_path:imagePath,truck_id:myTruck.id}});
 if(error)throw new Error('Gemini analysis request failed: '+(error.message||'Check Edge Function and API key.'));
 if(data?.error)throw new Error(data.error);
 const r=data?.readings;
 if(!r)throw new Error('Gemini did not return dashboard readings. Retake a clear photo.');
 const odo=typeof r.odometer_km==='number'&&Number.isFinite(r.odometer_km)?r.odometer_km:null;
 const fuel=typeof r.fuel_level_percent==='number'&&Number.isFinite(r.fuel_level_percent)&&r.fuel_level_percent>=0&&r.fuel_level_percent<=100?r.fuel_level_percent:null;
 if(odo===null&&fuel===null)throw new Error('AI could not read the odometer or fuel gauge. Retake a clear, well-lit dashboard photo.');
 return {imagePath,readings:{odometer_km:odo,fuel_level_percent:fuel,speed_kmh:r.speed_kmh??null,warning_lights:Array.isArray(r.warning_lights)?r.warning_lights:[],confidence:r.confidence||'low',needs_review:!!r.needs_review}};
}
function saveAIReadingRow(trip,eventType,pos,imagePath,readings,odo,fuelPct){
 const checkpointMap={start:'start_trip',break_start:'take_break',resume:'resume_trip',end:'end_ride'};
 const checkpoint=checkpointMap[eventType]||'start_trip';
 return sb.from('dashboard_ai_readings').insert({driver_id:session.user.id,truck_id:myTruck.id,trip_assignment_id:trip.id,checkpoint_type:checkpoint,image_path:imagePath,odometer_km:odo,fuel_level_percent:fuelPct,speed_kmh:readings.speed_kmh,warning_lights:readings.warning_lights,confidence:readings.confidence,needs_review:!!readings.needs_review,driver_confirmed:true,gps_lat:pos.coords.latitude,gps_lng:pos.coords.longitude,confirmed_at:new Date().toISOString()});
}
function fuelLabelFromPct(pct){if(pct===null||pct===undefined)return 'Not readable';if(pct<=10)return 'Empty / Reserve';if(pct<=30)return '1/4';if(pct<=60)return '1/2';if(pct<=85)return '3/4';return 'Full';}

function beginJourneyEvent(eventType){
 const trip=currentTrips.find(t=>t.status==='started');if(!trip)return toast2('There is no started trip to update.');
 if(!navigator.geolocation)return toast2('This browser does not support GPS.');
 if(!window.isSecureContext)return toast2('GPS and camera require HTTPS. Open the https:// driver site.');
 toast2('Getting a fresh GPS location…');
 navigator.geolocation.getCurrentPosition(pos=>openJourneyEventModal(trip,eventType,pos),err=>toast2(err.code===1?'Allow location permission in Chrome site settings.':err.code===2?'Turn on Location on the phone and try again.':'GPS timed out. Try again with a clear sky view.'),{enableHighAccuracy:true,maximumAge:0,timeout:25000});
}
function openJourneyEventModal(trip,eventType,pos){
 $('#fg-modal-shade')?.remove();
 const labels={break_start:'Start Break',resume:'Resume Trip',end:'End Ride'};const heading=labels[eventType]||'Journey checkpoint';
 const d=document.createElement('div');d.id='fg-modal-shade';d.innerHTML=`<div id="fg-modal" role="dialog" aria-modal="true" aria-labelledby="fg-journey-title"><h2 id="fg-journey-title">${heading} verification</h2><p>Upload a clear dashboard photo. AI will read the odometer and fuel gauge automatically; you can edit its results before saving.</p><form id="fg-journey-form"><label for="fg-journey-photo">Dashboard photo (required)</label><input id="fg-journey-photo" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" required/><p class="fg-mini">Use a clear photo showing the odometer and fuel gauge.</p><div id="fg-ai-status" class="fg-note">AI analysis will start after you select the photo and press Analyse dashboard.</div><label for="fg-journey-odo">AI odometer reading (km) — editable</label><input id="fg-journey-odo" type="number" min="0" max="9999999" step="0.1" placeholder="Filled by AI after analysis" required/><label for="fg-journey-pct">AI fuel percentage — editable</label><input id="fg-journey-pct" type="number" min="0" max="100" step="1" placeholder="Filled by AI after analysis" required/><label for="fg-journey-fuel">Fuel gauge category</label><select id="fg-journey-fuel" required><option value="">Select / confirm fuel level</option><option>Empty / Reserve</option><option>1/4</option><option>1/2</option><option>3/4</option><option>Full</option><option>Not readable</option></select><div class="fg-note"><b>GPS captured</b> ${Number(pos.coords.latitude).toFixed(5)}, ${Number(pos.coords.longitude).toFixed(5)} · Accuracy ±${Math.round(pos.coords.accuracy||0)} m</div><div id="fg-journey-error" role="alert"></div><div class="fg-modal-actions"><button type="button" id="fg-journey-cancel">Cancel</button><button class="primary" id="fg-journey-submit" type="submit">Analyse dashboard photo</button></div></form></div>`;document.body.append(d);
 $('#fg-journey-cancel').onclick=()=>d.remove();
 let analyzed=null;
 $('#fg-journey-form').addEventListener('submit',async e=>{
  e.preventDefault();const err=$('#fg-journey-error'),btn=$('#fg-journey-submit'),status=$('#fg-ai-status'),photo=$('#fg-journey-photo').files?.[0];
  if(!photo){err.textContent='Select a dashboard photo first.';return}
  if(!analyzed){
   btn.disabled=true;btn.textContent='AI analysing photo…';err.textContent='';status.textContent='Uploading private photo and asking Gemini to read the dashboard…';
   try{analyzed=await analyzeDashboardPhoto(photo,trip,eventType);const r=analyzed.readings;
    $('#fg-journey-odo').value=r.odometer_km??'';$('#fg-journey-pct').value=r.fuel_level_percent??'';$('#fg-journey-fuel').value=fuelLabelFromPct(r.fuel_level_percent);
    status.innerHTML=`<b>AI analysis complete</b><br>Odometer: ${r.odometer_km===null?'Not readable':r.odometer_km+' km'}<br>Fuel: ${r.fuel_level_percent===null?'Not readable':r.fuel_level_percent+'%'}<br>Confidence: ${safe(r.confidence)}<br>Warning lights: ${safe(r.warning_lights.join(', ')||'None detected')}<br><small>Edit the fields if needed, then press Confirm & save.</small>`;
    if(r.odometer_km===null||r.fuel_level_percent===null){status.innerHTML+='<br><b>Some reading was unclear.</b> Retake the photo or enter the missing value yourself before saving.';}
    btn.textContent='Confirm & save checkpoint';
   }catch(ex){status.textContent='AI analysis failed. No checkpoint was saved.';err.textContent=ex.message||'AI analysis failed';btn.textContent='Retry AI analysis';analyzed=null;}
   finally{btn.disabled=false;}return;
  }
  const odo=Number($('#fg-journey-odo').value),pct=Number($('#fg-journey-pct').value),fuel=$('#fg-journey-fuel').value;
  if(!Number.isFinite(odo)||odo<0){err.textContent='Enter or correct the odometer reading.';return}if(!Number.isFinite(pct)||pct<0||pct>100){err.textContent='Enter or correct fuel percentage from 0 to 100.';return}if(!fuel){err.textContent='Confirm the fuel gauge category.';return}
  btn.disabled=true;btn.textContent='Saving to database…';err.textContent='';
  try{
   const r={...analyzed.readings};const {error:aiSaveError}=await saveAIReadingRow(trip,eventType,pos,analyzed.imagePath,r,odo,pct);if(aiSaveError)throw aiSaveError;
   const {error:evErr}=await sb.from('trip_journey_events').insert({trip_id:trip.id,driver_id:session.user.id,truck_id:myTruck.id,event_type:eventType,dashboard_photo_path:analyzed.imagePath,odometer_km:odo,fuel_level:fuel,fuel_pct:Math.round(pct),lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy_m:pos.coords.accuracy||null,captured_at:new Date().toISOString()});if(evErr)throw evErr;
   if(eventType==='end'){const {data,error}=await sb.from('trip_assignments').update({status:'completed'}).eq('id',trip.id).eq('driver_id',session.user.id).eq('status','started').select('id').maybeSingle();if(error)throw error;if(!data)throw Error('Checkpoint saved, but trip status could not be updated.');if(gpsWatch!==null&&navigator.geolocation){navigator.geolocation.clearWatch(gpsWatch);gpsWatch=null}}
   d.remove();toast2(eventType==='break_start'?'Break started and checkpoint saved.':eventType==='resume'?'Trip resumed and checkpoint saved.':'Ride ended and final checkpoint saved.');await loadDriver({notify:false});
  }catch(ex){err.textContent='Save failed: '+(ex.message||'Unknown error');btn.disabled=false;btn.textContent='Retry save';}
 });
}

function ensureHistoryWhatsAppButton(){
 const page=$('#page-history');if(!page)return;
 let wrap=$('#fg-history-wa-share');if(!wrap){wrap=document.createElement('div');wrap.id='fg-history-wa-share';wrap.style.cssText='margin:0 0 16px;padding:14px 16px;border:1px solid #cfe6d7;background:#f2fbf5;border-radius:12px;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap';const title=page.querySelector('.page-title');if(title)title.after(wrap);else page.prepend(wrap)}
 wrap.innerHTML='<div><b style="display:block;color:#22543d">Share fuel submission with manager</b><small style="color:#557565">Sends fuel details and temporary private links to the saved WhatsApp number.</small></div><button type="button" id="fg-history-wa-btn" class="btn green">↗ Send on WhatsApp</button>';
 const b=$('#fg-history-wa-btn');b.disabled=!lastFuelSubmission;b.onclick=shareFuelToManagerWhatsApp;
}
async function loadDriverFuel(){const {data,error}=await sb.from('fuel_logs').select('*').eq('driver_id',session.user.id).order('created_at',{ascending:false}).limit(100);if(error)throw error;if(!lastFuelSubmission&&(data||[]).length){const f=data[0];if(f.bill_path&&f.video_path)lastFuelSubmission={id:f.id,truck_id:f.truck_id,station:f.station,litres:f.litres,amount:f.amount,bill_path:f.bill_path,video_path:f.video_path,created_at:f.created_at}}ensureHistoryWhatsAppButton();const body=$('#history-rows');if(body){body.replaceChildren();for(const f of data||[]){const tr=document.createElement('tr');[f.station||'—',new Date(f.created_at).toLocaleString(),`${f.litres} L`,`₹${Number(f.amount).toLocaleString('en-IN')}`,labelStatus(f.status)].forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.append(td)});body.append(tr)}if(!data?.length)body.innerHTML='<tr><td colspan="5" class="empty">No fuel submissions yet.</td></tr>'}if($('#history-count'))$('#history-count').textContent=(data||[]).length+' records';if($('#stat-logs'))$('#stat-logs').textContent=String((data||[]).length).padStart(2,'0');if($('#stat-amount'))$('#stat-amount').textContent='₹'+(data||[]).reduce((sum,x)=>sum+Number(x.amount||0),0).toLocaleString('en-IN');if($('#stat-pending'))$('#stat-pending').textContent=String((data||[]).filter(x=>x.status==='pending').length).padStart(2,'0');}
async function submitFuel(e){e.preventDefault();const form=e.currentTarget,bill=$('#bill-file')?.files?.[0],video=$('#video-file')?.files?.[0];if(!myTruck)return toast2('No vehicle assigned. Ask the manager to assign a vehicle before submitting fuel.');if(!bill||!video)return toast2('Bill photo and pump video are both required.');if(bill.size>15*1024*1024||video.size>15*1024*1024)return toast2('Each proof file must be 15 MB or smaller.');const station=$('#station').value.trim(),litres=Number($('#litres').value),amount=Number($('#amount').value);if(!station||!(litres>0)||!(amount>0))return toast2('Enter valid station, litres and amount.');const submit=form.querySelector('button[type="submit"]');if(submit){submit.disabled=true;submit.textContent='Uploading securely…'}try{const id=crypto.randomUUID(),base=`${session.user.id}/${myTruck.id}/${id}`;const uploads=[];for(const [file,suffix] of [[bill,'bill'],[video,'pump-video']]){const ext=(file.name.split('.').pop()||'bin').toLowerCase().replace(/[^a-z0-9]/g,'').slice(0,8)||'bin';const path=`${base}-${suffix}.${ext}`;const {error}=await sb.storage.from('fuel-proofs').upload(path,file,{upsert:false,contentType:file.type||undefined});if(error)throw error;uploads.push(path)}const {error}=await sb.from('fuel_logs').insert({truck_id:myTruck.id,driver_id:session.user.id,station,litres,amount,bill_path:uploads[0],video_path:uploads[1],status:'pending'});if(error)throw error;lastFuelSubmission={id,truck_id:myTruck.id,station,litres,amount,bill_path:uploads[0],video_path:uploads[1],created_at:new Date().toISOString()};ensureHistoryWhatsAppButton();const wa=$('#wa-btn');if(wa){wa.disabled=false;wa.textContent='↗ Send fuel details and proof links to manager on WhatsApp'}toast2('Fuel log and private proofs uploaded. You can now share the details with your manager on WhatsApp.');form.reset();$('#bill-name').textContent='';$('#video-name').textContent='';$('#bill-box')?.classList.remove('done');$('#video-box')?.classList.remove('done');await loadDriverFuel();showPage('history')}catch(err){toast2('Submission failed: '+(err.message||'Unknown error'));}finally{if(submit){submit.disabled=false;submit.textContent='⇧ Submit fuel log for review →'}}}
async function updateDriverTrip(status, verifiedStart=false){
 if(status==='started'&&!verifiedStart)return beginTripStartVerification();
 const trip=currentTrips.find(t=>['assigned','started'].includes(t.status));
 if(!trip)return toast2('No active trip assigned by the manager.');
 if(status==='started'&&trip.status!=='assigned')return toast2('Trip has already started.');
 if(status==='completed'&&trip.status!=='started')return toast2('Start the trip before marking it complete.');
 const {data,error}=await sb.from('trip_assignments').update({status}).eq('id',trip.id).eq('driver_id',session.user.id).select('id,status').maybeSingle();
 if(error)return toast2('Trip update failed: '+error.message);
 if(!data)return toast2('Trip status was not saved. Refresh the page and check your assignment permissions.');
 if(status==='completed'&&gpsWatch!==null&&navigator.geolocation){navigator.geolocation.clearWatch(gpsWatch);gpsWatch=null;}
 toast2(status==='started'?'Trip started. Live GPS tracking is now active while this page remains active.':'Trip marked completed.');
 await loadDriver({notify:false});
 if(status==='started'){startGPS();}
}
async function beginTripStartVerification(){
 const trip=currentTrips.find(t=>t.status==='assigned');
 if(!trip)return toast2('No assigned trip is ready to start.');
 if(!myTruck)return toast2('No vehicle assigned. Ask your manager to assign one first.');
 if(!navigator.geolocation)return toast2('This browser does not support location access.');
 if(!window.isSecureContext)return toast2('Location and camera require HTTPS. Open the deployed site using its https:// address.');
 toast2('Requesting location permission…');
 navigator.geolocation.getCurrentPosition(pos=>openTripStartEvidenceModal(trip,pos),err=>{
  const msg=err.code===1?'Location permission denied. Allow location for this site in Chrome settings, then retry.':err.code===2?'Location is unavailable. Turn on Location in your phone settings and retry.':'Could not get a fresh GPS fix. Check phone Location and try again.';
  toast2(msg);
 },{enableHighAccuracy:true,maximumAge:0,timeout:25000});
}
function openTripStartEvidenceModal(trip,pos){
 $('#fg-modal-shade')?.remove();
 const d=document.createElement('div');d.id='fg-modal-shade';d.innerHTML=`<div id="fg-modal" role="dialog" aria-modal="true" aria-labelledby="fg-trip-start-title"><h2 id="fg-trip-start-title">Trip start verification</h2><p>Upload a clear dashboard photo. Gemini AI will automatically extract odometer and fuel readings. You can edit before saving.</p><form id="fg-trip-start-form"><label for="fg-trip-photo">Dashboard photo (required)</label><input id="fg-trip-photo" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" required/><p class="fg-mini">The image is uploaded to private dashboard storage.</p><div id="fg-trip-ai-status" class="fg-note">Select a photo and press Analyse dashboard.</div><label for="fg-trip-odo">AI odometer (km) — editable</label><input id="fg-trip-odo" type="number" min="0" max="9999999" step="0.1" required placeholder="Filled automatically by AI"/><label for="fg-trip-fuel-pct">AI fuel percentage — editable</label><input id="fg-trip-fuel-pct" type="number" min="0" max="100" step="1" required placeholder="Filled automatically by AI"/><label for="fg-trip-fuel">Fuel gauge category</label><select id="fg-trip-fuel" required><option value="">Select / confirm fuel level</option><option>Empty / Reserve</option><option>1/4</option><option>1/2</option><option>3/4</option><option>Full</option><option>Not readable</option></select><div class="fg-note"><b>GPS captured</b> ${Number(pos.coords.latitude).toFixed(5)}, ${Number(pos.coords.longitude).toFixed(5)} · Accuracy ±${Math.round(pos.coords.accuracy||0)} m</div><div id="fg-trip-start-error" role="alert"></div><div class="fg-modal-actions"><button type="button" id="fg-trip-cancel">Cancel</button><button class="primary" id="fg-trip-submit" type="submit">Analyse dashboard photo</button></div></form></div>`;document.body.append(d);
 $('#fg-trip-cancel').onclick=()=>d.remove();let analyzed=null;
 $('#fg-trip-start-form').addEventListener('submit',async e=>{
  e.preventDefault();const err=$('#fg-trip-start-error'),btn=$('#fg-trip-submit'),status=$('#fg-trip-ai-status'),photo=$('#fg-trip-photo').files?.[0];if(!photo){err.textContent='Select a dashboard photo.';return}
  if(!analyzed){btn.disabled=true;btn.textContent='AI analysing photo…';err.textContent='';status.textContent='Uploading private photo and analysing dashboard with Gemini…';try{analyzed=await analyzeDashboardPhoto(photo,trip,'start');const r=analyzed.readings;$('#fg-trip-odo').value=r.odometer_km??'';$('#fg-trip-fuel-pct').value=r.fuel_level_percent??'';$('#fg-trip-fuel').value=fuelLabelFromPct(r.fuel_level_percent);status.innerHTML=`<b>AI analysis complete</b><br>Odometer: ${r.odometer_km===null?'Not readable':r.odometer_km+' km'}<br>Fuel: ${r.fuel_level_percent===null?'Not readable':r.fuel_level_percent+'%'}<br>Confidence: ${safe(r.confidence)}<br>Warning lights: ${safe(r.warning_lights.join(', ')||'None detected')}<br><small>Edit if required, then press Confirm & start trip.</small>`;btn.textContent='Confirm & save evidence / start trip';}catch(ex){status.textContent='AI analysis failed. Trip was not started.';err.textContent=ex.message||'AI analysis failed';analyzed=null;btn.textContent='Retry AI analysis'}finally{btn.disabled=false}return}
  const odo=Number($('#fg-trip-odo').value),pct=Number($('#fg-trip-fuel-pct').value),fuel=$('#fg-trip-fuel').value;if(!Number.isFinite(odo)||odo<0){err.textContent='Enter or correct odometer.';return}if(!Number.isFinite(pct)||pct<0||pct>100){err.textContent='Enter or correct fuel percentage from 0 to 100.';return}if(!fuel){err.textContent='Confirm the fuel gauge category.';return}
  btn.disabled=true;btn.textContent='Saving trip evidence…';err.textContent='';try{const r=analyzed.readings;const {error:aiErr}=await saveAIReadingRow(trip,'start',pos,analyzed.imagePath,r,odo,pct);if(aiErr)throw aiErr;
   const record={trip_id:trip.id,driver_id:session.user.id,truck_id:myTruck.id,dashboard_photo_path:analyzed.imagePath,odometer_km:odo,fuel_level:fuel,fuel_pct:Math.round(pct),lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy_m:pos.coords.accuracy||null,captured_at:new Date().toISOString()};const {error:evErr}=await sb.from('trip_start_evidence').insert(record);if(evErr)throw evErr;const {error:journeyErr}=await sb.from('trip_journey_events').insert({...record,event_type:'start'});if(journeyErr)throw journeyErr;
   d.remove();await updateDriverTrip('started',true);
  }catch(ex){err.textContent='Could not save/start trip: '+(ex.message||'Unknown error');btn.disabled=false;btn.textContent='Retry save / start trip'}
 });
}

async function shareFuelToManagerWhatsApp(){
 if(!lastFuelSubmission)return toast2('Submit the fuel log with bill photo and pump video first.');
 const btn=$('#wa-btn');let popup=null;if(btn){btn.disabled=true;btn.textContent='Preparing secure links…'}
 // Open the window synchronously from the user's click to avoid popup blockers.
 popup=window.open('about:blank','_blank');
 try{
  const {data:settings,error:settingsError}=await sb.from('fleet_settings').select('whatsapp_number').eq('id',true).maybeSingle();if(settingsError)throw settingsError;
  const number=String(settings?.whatsapp_number||'').replace(/\D/g,'');if(number.length<10)throw Error('Manager has not saved a valid WhatsApp number yet. Ask the manager to set it under Manager → Settings.');
  const [bill,video]=await Promise.all([sb.storage.from('fuel-proofs').createSignedUrl(lastFuelSubmission.bill_path,604800),sb.storage.from('fuel-proofs').createSignedUrl(lastFuelSubmission.video_path,604800)]);
  if(bill.error)throw bill.error;if(video.error)throw video.error;
  const truck=myTruck?.reg_no||myTruck?.id||lastFuelSubmission.truck_id;
  const message=[
   'FuelGuard PRO — Fuel Log Submission',
   `Driver: ${me.full_name||session.user.email}`,
   `Vehicle: ${truck}`,
   `Station: ${lastFuelSubmission.station}`,
   `Fuel quantity: ${lastFuelSubmission.litres} L`,
   `Total amount: ₹${Number(lastFuelSubmission.amount).toLocaleString('en-IN')}`,
   `Submitted: ${new Date(lastFuelSubmission.created_at).toLocaleString()}`,
   `Bill photo (secure link, expires in 7 days): ${bill.data.signedUrl}`,
   `Pump video (secure link, expires in 7 days): ${video.data.signedUrl}`,
   '',
   'Please review this fuel submission. The links are private and temporary.'
  ].join('\n');
  const url=`https://wa.me/${number}?text=${encodeURIComponent(message)}`;
  if(popup&&!popup.closed)popup.location.href=url;else window.location.href=url;
  toast2('WhatsApp draft prepared for the manager. Review it and press Send.');
 }catch(e){if(popup&&!popup.closed)popup.close();toast2('WhatsApp share failed: '+e.message)}finally{if(btn){btn.disabled=false;btn.textContent='↗ Send fuel details and proof links to manager on WhatsApp'}}
}
async function driverSOS(){if(!myTruck)return toast2('No vehicle assigned. Contact your manager.');if(!confirm('Send an SOS alert to your fleet manager now?'))return;const {error}=await sb.from('alerts').insert({truck_id:myTruck.id,type:'sos',message:`SOS from ${me.full_name||session.user.email}`,severity:'critical',resolved:false});if(error)return toast2('SOS could not be sent: '+error.message);toast2('SOS sent to your manager. If this is an emergency, contact local emergency services too.')}
function startGPS(){
 if(!myTruck){toast2('No vehicle assigned. Ask your manager to assign one first.');return}
 if(!navigator.geolocation){toast2('GPS is not supported by this browser.');return}
 if(!window.isSecureContext){toast2('GPS needs HTTPS. Open the driver site using its https:// address.');return}
 const b=$('#gps-btn');
 if(gpsWatch!==null){
  navigator.geolocation.clearWatch(gpsWatch);gpsWatch=null;
  if(b)b.textContent='⌖ Start GPS tracking';
  toast2('GPS tracking stopped.');return;
 }
 if(b){b.disabled=true;b.textContent='Requesting GPS permission…';}
 navigator.geolocation.getCurrentPosition(pos=>{
  if(b){b.disabled=false;b.textContent='GPS connected · syncing…';}
  const sendPosition=async p=>{
   const now=Date.now();if(now-lastGpsSent<15000)return;lastGpsSent=now;
   const lat=p.coords.latitude,lng=p.coords.longitude,speed=Math.max(0,Math.round((p.coords.speed||0)*3.6));
   if(b){b.disabled=false;b.textContent='GPS connected · saving…';b.title=`Lat ${lat.toFixed(5)}, Lng ${lng.toFixed(5)} · Accuracy ±${Math.round(p.coords.accuracy||0)} m`;}
   try{
    const {error}=await sb.from('gps_pings').insert({truck_id:myTruck.id,lat,lng,speed,fuel_pct:myTruck.fuel_pct??null});
    if(error)throw error;
    const {error:truckError}=await sb.from('trucks').update({lat,lng,speed,status:speed>3?'running':'stopped',updated_at:new Date().toISOString()}).eq('id',myTruck.id);
    if(truckError)throw truckError;
    if(b)b.textContent='■ Stop GPS tracking';
   }catch(e){
    if(b)b.textContent='GPS connected · upload failed';
    toast2('GPS is working, but Supabase did not save the location: '+(e.message||'Check gps_pings/trucks permissions and network.'));
   }
  };
  sendPosition(pos);
  gpsWatch=navigator.geolocation.watchPosition(sendPosition,err=>{
   const msg=err.code===1?'GPS permission denied. In Chrome, tap the site icon → Permissions → Location → Allow, then retry.':err.code===2?'GPS position unavailable. Turn on Location on the phone and try outdoors.':'GPS timed out. Keep the page open, enable phone Location, and retry.';
   if(b){b.disabled=false;b.textContent='GPS error · Tap to retry';}
   toast2(msg);
  },{enableHighAccuracy:true,maximumAge:5000,timeout:30000});
  toast2('GPS connected. Keep this page open for live updates; Chrome may pause tracking in the background.');
 },err=>{
  const msg=err.code===1?'Location permission denied. In Chrome, open site settings → Location → Allow, then reload.':err.code===2?'Phone Location is off or GPS is unavailable. Turn on Location and retry.':'GPS timed out. Move somewhere with a clearer sky view and retry.';
  if(b){b.disabled=false;b.textContent='GPS unavailable · Tap to retry';}
  toast2(msg);
 },{enableHighAccuracy:true,maximumAge:0,timeout:30000});
}
function subscribeLive(){if(liveChannel)sb.removeChannel(liveChannel);const tables=isManager?['trucks','profiles','fuel_logs','trip_assignments','alerts','gps_pings']:['trucks','fuel_logs','trip_assignments','alerts'];liveChannel=sb.channel('fuelguard-'+session.user.id);for(const table of tables)liveChannel=liveChannel.on('postgres_changes',{event:'*',schema:'public',table},()=>{clearTimeout(window.__fgRefresh);window.__fgRefresh=setTimeout(()=>{if(isManager)loadManager().catch(e=>toast2(e.message));else{sb.from('profiles').select('id,role,full_name,mobile,truck_id').eq('id',session.user.id).single().then(async r=>{if(r.error)throw r.error;me=r.data;myTruck=null;if(me.truck_id){const v=await sb.from('trucks').select('*').eq('id',me.truck_id).maybeSingle();if(v.error)throw v.error;myTruck=v.data}await loadDriver()}).catch(e=>toast2(e.message))}},600)});liveChannel.subscribe();}
